-- Approved by the user on 2026-10-16. No reservation or historical tariff updates.
DO $$ BEGIN
 IF EXISTS(SELECT 1 FROM habitaciones WHERE numero IN('106','107','109','205','206','207','304','305','306','307')) THEN RAISE EXCEPTION 'Approved new room number already exists; review before applying'; END IF;
 IF EXISTS(SELECT 1 FROM reservas WHERE tipo_habitacion_id IN (SELECT tipo_habitacion_id FROM catalogo_configuraciones WHERE clave IN ('D2','D3','S3','F4','F5','P4','DT3','P5'))) THEN RAISE EXCEPTION 'New commercial types already have reservations; review before updating descriptions'; END IF;
END $$;
CREATE TABLE caracteristicas_habitacion(habitacion_id bigint PRIMARY KEY REFERENCES habitaciones(id),contenido jsonb NOT NULL CHECK(jsonb_typeof(contenido)='object'),procedencia text NOT NULL,actualizado_en timestamptz NOT NULL DEFAULT now());
